    // Verify all numeric summary values are present
    const summaryValues = summaryRow.locator('td');
    const valueCount = await summaryValues.count();
    expect(valueCount).toBe(5); // Product name + 4 numeric columns

    // Verify specific summary values
    const q1Summary = summaryValues.nth(1);
    await expect(q1Summary).toContainText('47000');

    const q2Summary = summaryValues.nth(2);
    await expect(q2Summary).toContainText('53000');

    const q3Summary = summaryValues.nth(3);
    await expect(q3Summary).toContainText('61000');

    const totalSummary = summaryValues.nth(4);
    await expect(totalSummary).toContainText('161000');
  });

  test('should position summary row after all data rows', async ({ page }) => {
    // Get all rows in the table
    const allRows = page.locator('table#sales-table tbody tr');
    const rowCount = await allRows.count();

